import regionPaths from "@/data/region-paths.json"

// Real GCC/Levant border geometry (Natural Earth 1:50m, Mercator-projected)
// for the brand's seven markets, plus immediate neighbours for context.
// Generated by scripts/geo — not hand-traced, so the shapes read as an
// actual map rather than an abstract silhouette.
const links: [string, string][] = [
  ["uae", "ksa"],
  ["uae", "qatar"],
  ["ksa", "kuwait"],
  ["ksa", "jordan"],
  ["kuwait", "lebanon"],
  ["jordan", "lebanon"],
  ["jordan", "egypt"],
  ["egypt", "lebanon"],
  ["uae", "kuwait"],
]

const focusEntries = Object.entries(regionPaths.focus)
const contextEntries = Object.entries(regionPaths.context)

function centroid(id: string) {
  return regionPaths.focus[id as keyof typeof regionPaths.focus]
}

export function RegionMap({ className }: { className?: string }) {
  return (
    <svg
      viewBox={regionPaths.viewBox}
      className={`${className ?? ""} motion-safe:animate-[map-drift_50s_ease-in-out_infinite]`}
      fill="none"
      aria-hidden="true"
    >
      {/* neighbouring countries — faint outline only, no glow */}
      <g className="text-navy-300" opacity="0.22">
        {contextEntries.map(([id, c]) => (
          <path key={id} d={c.d} fill="none" stroke="currentColor" strokeWidth="0.22" strokeLinejoin="round" />
        ))}
      </g>

      {/* the seven markets — glowing outline over a soft fill */}
      <g style={{ filter: "drop-shadow(0 0 1.4px currentColor) drop-shadow(0 0 3.2px currentColor)" }}>
        {focusEntries.map(([id, c]) => (
          <path
            key={id}
            d={c.d}
            fill="currentColor"
            fillOpacity="0.1"
            stroke="currentColor"
            strokeOpacity="0.85"
            strokeWidth="0.32"
            strokeLinejoin="round"
            className="text-petrol-300"
          />
        ))}
      </g>

      {links.map(([a, b], i) => {
        const na = centroid(a)
        const nb = centroid(b)
        return (
          <line
            key={`${a}-${b}`}
            x1={na.cx}
            y1={na.cy}
            x2={nb.cx}
            y2={nb.cy}
            stroke="currentColor"
            strokeOpacity="0.35"
            strokeWidth="0.25"
            strokeDasharray="1.2 3"
            className="text-navy-100 motion-safe:animate-[signal-travel_6s_linear_infinite]"
            style={{ animationDelay: `${i * 0.7}s` }}
          />
        )
      })}
      {focusEntries.map(([id, c], i) => (
        <g key={id} className="text-navy-100">
          <circle
            cx={c.cx}
            cy={c.cy}
            r="2.6"
            stroke="currentColor"
            strokeOpacity="0.25"
            strokeWidth="0.2"
            className="motion-safe:animate-gentle-pulse"
            style={{ animationDelay: `${i * 0.45}s` }}
          />
          <circle cx={c.cx} cy={c.cy} r="0.9" fill="currentColor" />
        </g>
      ))}
    </svg>
  )
}
